 ]
 public static let entries: [VeilopolyCompleteManualEntry] = [
  .init(id: "intro-identity", chapter: "intro", title: "这是什么游戏", subtitle: "四位玩家、一座城市、一套共享状态", paragraphs: ["Veilopoly 是 VeilLink 生态内的原创、大富翁式虚拟经济桌游。棋盘共有 40 格，四个玩家席位；单机可由一个或多个本地人类席位配合 AI 席位进行。游戏币仅用于本游戏，不属于现实货币、证券或可兑换资产。", "规则采用确定性的 GameState 状态机：每次合法行动都会产生新的状态和可视化效果；被拒绝的行动不应修改存档或虚拟资金。", "本书以 2026 年 11 月 8 日读取的独立研发分支为准，不代表已经发布到已安装 IPA。"], evidence: "Models.swift；Board.swift；Rules.swift；Package.swift"),
  .init(id: "intro-readme", chapter: "intro", title: "先阅读这个版本告知", subtitle: "“源码存在”和“手机可玩”不是同一回事", paragraphs: ["本书详细解释源码定义的经典版、V3、V4 与实验性 V5。实际进入哪套规则，应以正在载入的对局银行账本 financeRuleVersion 和当前棋盘快照为准，不能只根据 App 图标或安装日期判断。", "当前 V5 包含资金池、风险等级、待兑付债权和金融遗产继承的研发实现，但尚未完成该分支的全部 SwiftPM、iOS 模拟器和真机验收；因此说明书标为“研发实现，待验收”。", "阅读本书不会改变资产、掷骰次数、股票行情、随机种子或联机状态。"], evidence: "VeilopolyCityLongEconomy.swift；VeilopolyFinancialStability.swift；CHECKPOINT.md"),
  .init(id: "intro-version", chapter: "intro", title: "规则版本怎么区分", subtitle: "不可将 V5 数值套入旧存档", paragraphs: ["经典 GameFactory 的初始现金为每人 ¥1,500，经过起点为 ¥200；旧金融存档可能没有有限银行资金池。V3 的初始现金 ¥7,200，经典卡牌曾经不同；V4 建立 ¥160,000 银行储备和四人各 ¥7,200 的总额 ¥188,800。", "新开单机 V5 的银行储备为 ¥2,000,000、玩家初始现金每人 ¥25,000，共 ¥2,100,000 个游戏币。旧 V4 档位不会因安装新源码自动改成 V5；读取旧存档时应继续执行原规则。", "V5 双手机联机的经济版本协商尚未完成，因此不要把联机经典局写成已经采用 V5。"], evidence: "VeilopolyCityLongEconomy.swift；LiveRoom.swift"),
  .init(id: "intro-money", chapter: "intro", title: "钱的四种含义", subtitle: "现金、储备、合同资产和待兑付债权", paragraphs: ["“玩家现金”是当前可直接用于合法买地、支付租金、还款、买股票的余额。“银行储备”是中央银行尚未支付出去的游戏币。“合同资产”指存款本金、投资持仓、股票市值等；它们不是玩家当前现金。", "“待兑付债权”是银行承认欠付的数额，记入队列，但尚未变为实际到手的现金；不能直接用它买地或还款。V5 的会计恒等式是银行储备＋四名玩家现金＝¥2,100,000，不把债权或股票市值重复算为货币。", "仅当交易已经由规则引擎成功提交，余额和产权才真正变化。"], evidence: "IntegratedBanking.swift；Rules.swift；VeilopolyFinancialStability.swift"),
  .init(id: "intro-trust", chapter: "intro", title: "如何理解说明书的准确性", subtitle: "字段名、数值和验收标记", paragraphs: ["本书使用“已在源码中实现”“仍待验收”“尚未实现”三种表述：前者不等于通过设备测试；“尚未实现”尤其适用于 V5 双机联机、真实订单簿以及真实公司财务模型。", "银行、股票和概率事件涉及的示例均为游戏币计算。任何收益率仅作用于具体虚拟合同；不保证每局赚钱，不是现实投资建议。", "涉及税收、工资、租金、金融期数的金额，先确认对局版本，再以页面即时规则引擎回执为最终执行结果。"], evidence: "VeilopolyGuideLibrary.swift；CHECKPOINT.md"),
  .init(id: "start-enter", chapter: "start", title: "打开完整规则手册", subtitle: "手册入口与旧词条并存", paragraphs: ["游戏内已有“城市玩家手册”入口；本轮将在该界面新增“完整规则说明书”的导航入口，而不是删除原来的 23 个玩法辞典词条。点击入口后可以按章浏览，也能搜索“贷款”“破产”“木板路”“VTL”等文字。", "文档页面是只读视图，关闭后返回原对局。若设备仍运行旧 IPA，可能看不到新入口；必须以集成并完成设备构建后的版本为准。"], evidence: "VeilopolyGuideSheet.swift；VeilopolyGuideLibrary.swift"),
  .init(id: "start-newgame", chapter: "start", title: "新建单机对局", subtitle: "一局由确定性种子定义", paragraphs: ["新的 V5 单机局由 VeilopolyCityLongEconomy.make 生成：四席位、40 格棋盘、32 张 V5 机会／命运牌、银行资金池与股票初始状态都在同一份 GameState 内。", "“重新开始”会按游戏界面实际行为创建新局；正在继续的旧存档则不会自动重估资产价值。开始之前尽量确认你希望保存哪一局；本书不保证覆盖旧存档后能恢复。"], evidence: "VeilopolyCityLongEconomy.swift；GameSaveStore.swift"),
  .init(id: "start-turn", chapter: "start", title: "一回合的标准顺序", subtitle: "掷骰 → 移动 → 落点 → 资产管理 → 结束", paragraphs: ["轮到当前玩家时，在允许的掷骰阶段点击“掷骰子”。引擎记录两个六面骰结果，将棋子移动相应格数并处理落点的购地、租金、税费、卡牌或监狱效果。", "进入“资产管理”阶段后，可根据按钮允许的范围建房、卖房、抵押、赎回、存款、贷款、证券买卖或发起交易；点击“结束回合”才交给下一位未破产玩家。不是任何阶段都能随意买卖。", "若正在等待拍卖、交易确认或债务清算，引擎会限制可操作项；按钮变灰一般是状态或条件限制，不等于触摸失灵。"], evidence: "Rules.swift；UI.swift"),
  .init(id: "start-select", chapter: "start", title: "选中地块不等于购买", subtitle: "区分浏览动作和资金操作", paragraphs: ["在棋盘上触摸地块是查看资产信息：名称、所有者、抵押、房屋以及当前租金等。只有在正式落点后，界面提供“购买地产”或“开始拍卖”等可执行指令，提交成功才会扣款与登记所有权。", "浏览纸质风格的地契登记簿、拍卖公告和银行存根也不会触发交易；这些文书展示的是当前 GameState 的快照。"], evidence: "UI.swift；VeilopolyCivicText.swift"),
  .init(id: "start-double", chapter: "start", title: "相同点数与额外回合", subtitle: "连续第三次双骰入狱", paragraphs: ["非监狱玩家掷出两颗相同点数时，符合条件可再掷一次；同一串行动连续第三次掷出双骰，会被送入监狱。", "在监狱中掷出双骰可以获释，但不会因该次双骰再触发额外回合；具体先后以引擎回执为准。"], evidence: "Rules.swift: rollDice；endTurn"),
  .init(id: "start-jail", chapter: "start", title: "监狱的三个离开途径", subtitle: "掷出双骰、出狱卡、保释", paragraphs: ["入狱后，可以按照当前阶段的允许操作掷骰尝试获释，也可使用“机会／命运出狱卡”或支付保释费用。V5 保释金额为 ¥600；V4/V3 为 ¥150；经典局为 ¥50。", "监狱剩余次数归零时的强制保释也按当前规则版本收费；现金不足可能进入债务清算，而不是免费放人。"], evidence: "Rules.swift；VeilopolyCityLongEconomy.swift"),
  .init(id: "start-go", chapter: "start", title: "经过起点的收入", subtitle: "V5 为 ¥3,200，旧局不同", paragraphs: ["正常掷骰移动跨过第 0 格时领取该局的起点工资；V5 为 ¥3,200，V4/V3 为 ¥1,100，经典版为 ¥200。卡牌移动到起点或经过起点时，应以卡牌所含的 collectGo 标志和引擎结算回执为准。", "V5 的工资由中央银行支付：银行流动性不足时并不许可凭空增发；未支付部分可能转为银行债权，到账现金会小于理论工资。"], evidence: "Rules.swift: applyMovement, payBank；VeilopolyCityLongEconomy.swift"),
  .init(id: "start-controls", chapter: "start", title: "手机屏幕与按钮", subtitle: "点击、滚动与数字输入", paragraphs: ["建议在较宽的屏幕布局中查看完整棋盘和金融面板。游戏采用 SwiftUI 的滚动面板、菜单选择、数值输入与分阶段按钮；触摸棋盘负责选中，交易由专门按钮提交。", "旧版最低平台声明为 iOS 15，但在当前分支上尚无完成的苹果 SDK 与 iPhone 7 真机验收记录。不要因为 Swift Package 的源码存在，就把低版本触摸和性能标为已经保证。"], evidence: "Package.swift；UI.swift；VeilopolyGuideSheet.swift"),
  .init(id: "start-time", chapter: "start", title: "一局为什么可能很快结束", subtitle: "实际时长尚无最终统计", paragraphs: ["当前胜利条件以其他玩家破产淘汰为核心，并未把 40～60 分钟设置为真实胜利门槛。V5 通过较高的起始资金、工资和渐进式租金上限试图降低早期淘汰，但能否真正延长游戏，需要人类计时和多种子完成率数据。", "工程中已有 100 种子压力测试源码，但尚未运行；测试步数上限不是“已自然结束的局数”，行动数也不能直接转换为分钟数。"], evidence: "Rules.swift；MacroFinalSeedStressTests.swift；CHECKPOINT.md"),
  .init(id: "board-overview", chapter: "board", title: "棋盘由 40 格组成", subtitle: "格子编号从 0 到 39", paragraphs: ["棋盘顺时针编号 0～39，依次存在起点、街区、铁路、公共事业、机会、命运、监狱、税费、免费停车等地块。每一格的中文名称、类型、经典底价和 V5 对应价格在本书附录全部列出。", "玩家由当前位置加上两骰点数移动，并对 40 取模；如果经过起点，则另行按照当前规则处理工资。"], evidence: "Board.swift；Rules.swift"),
  .init(id: "board-special", chapter: "board", title: "不可购买的特殊格", subtitle: "触发效果，不发产权", paragraphs: ["第 0 格为起点；第 2、17、33 格为命运；第 7、22、36 格为机会；第 4 和 38 格是税收；第 10 格为监狱／探访；第 20 格为免费停车；第 30 格会直接送入监狱。", "在“免费停车”上不会自动获得现实收入或自定义奖金；不要从实体桌游的家规推断此游戏会出现同样规则。"], evidence: "Board.swift；Rules.swift"),
  .init(id: "board-streets", chapter: "board", title: "街区有八种颜色组", subtitle: "只有成组控制才能建造", paragraphs: ["街区颜色为棕、浅蓝、粉、橙、红、黄、绿、深蓝。组内全部地块属于同一人，并满足未抵押及建筑均衡条件时，才能正式建房或升旅馆。", "一条街道既可能产生基础租金，也可能因成套拥有和建筑等级带来不同租金；V5 还受本期单次租金上限限制。"], evidence: "Board.swift；Rules.swift"),
  .init(id: "board-rail", chapter: "board", title: "铁路和公共事业", subtitle: "有产权但不能建造房屋", paragraphs: ["第 5、15、25、35 格为铁路；第 12、28 格为公共事业。铁路的基础租金取决于同一所有者持有的铁路数，公共事业租金由最近掷骰点数与持有数量决定。", "它们不是街区，不能在上面建住宅和旅馆。V5 的铁路和公共事业基础租金会按长局规则倍数调整，再应用单次租金保护上限。"], evidence: "Board.swift；Rules.swift；VeilopolyCityLongEconomy.swift"),
  .init(id: "board-tax", chapter: "board", title: "税费格怎样扣款", subtitle: "税费由版本及落点共同确定", paragraphs: ["所得税位于第 4 格，奢侈税位于第 38 格。V5 分别为 ¥2,200 与 ¥1,100；V4/V3 分别为 ¥600 与 ¥300；经典局则是 ¥200 与 ¥100。", "向银行支付税费会增加中央银行现金储备；若玩家现金不够，执行的是债务逻辑，不是透支负数现金。"], evidence: "Rules.swift；VeilopolyCityLongEconomy.swift"),
  .init(id: "property-buy", chapter: "property", title: "购买无主产权", subtitle: "落点出现购买按钮才可成交", paragraphs: ["当玩家停在没有所有者的街区、铁路或公共事业时，选择“购买”并满足现金条件，才会扣除该地块标价并登记所有权。V5 的可购买地块标价以经典表的 12 倍计算。", "例如经典棕色地中海大道标价 ¥60，新 V5 标价为 ¥720；买下后玩家现金减少 ¥720，银行储备按相同金额回流。"], evidence: "Board.swift；VeilopolyCityLongEconomy.swift；Rules.swift"),
  .init(id: "property-auction", chapter: "property", title: "不购买时进入拍卖", subtitle: "按顺序出价或退出", paragraphs: ["当玩家放弃直接购买无主地块，可进入拍卖状态。参与者轮流报出正整数金额或退出；新报价必须大于当前最高价，且不得超过本人可用现金。", "只有拍卖结束且由引擎认定中标，才会扣除出价并将地产归入中标者名下；正在显示的拍卖公告只是竞价快照，没有自动计时的保证。"], evidence: "Rules.swift: startAuction, bid；VeilopolyCivicText.swift"),
  .init(id: "property-build", chapter: "property", title: "建一栋房屋的全部前置条件", subtitle: "完整地组、无抵押、均衡与库存", paragraphs: ["玩家必须拥有目标街区所属颜色组的所有街道，而且整组不能存在抵押；目标地块的建筑等级须等于该组最低等级，不能在同组某个格子单独跳级。", "银行实体房屋库存起始为 32 栋、旅馆为 12 座。目标地块已有 4 栋房时，下一次合法建设可升 1 座旅馆，同时把 4 栋房退还银行。建设费来自该地块 houseCost：V5 为经典成本的 12 倍。"], evidence: "Rules.swift: buildHouse；Models.swift: Bank"),
  .init(id: "property-freehouse", chapter: "property", title: "免费建房卡真的能建房吗", subtitle: "机遇与命运各有一张大事件", paragraphs: ["V5 机会卡编号 13“城市建设特许令”与命运卡编号 27“旧城复兴工程”可以无现金费用建造一栋合法房屋。目标仍须在玩家完整、未抵押的颜色组中，并满足均衡建造和银行剩余房屋库存。", "如果没有合法位置或者银行没有可用房屋，则分别从银行领取替代奖励 ¥3,200 或 ¥2,400。替代奖励同样受 V5 银行实际流动性和待兑付规则影响，不代表必定立即到账。"], evidence: "VeilopolyCityLongCards.swift；Rules.swift: grantHouse"),
  .init(id: "property-rent", chapter: "property", title: "租金如何产生", subtitle: "由地块、所有权、骰点与版本决定", paragraphs: ["停在其他玩家拥有、未抵押的地块上，按引擎计算租金并付给产权人；拥有完整同色组但尚未建房，街区基础租金可能翻倍。铁路和公共事业采用不同的计算逻辑。", "V5 街区的基础租金表是经典表的 8 倍，铁路、公用事业基础租金按长局公式调整；单次实收租金不得超过本期租金上限。真正支付的金额以租金回执为准。"], evidence: "Rules.swift: rent；VeilopolyCityLongEconomy.swift"),
  .init(id: "property-rent-cap", chapter: "property", title: "为什么豪华旅馆不一定收全额", subtitle: "渐进租金上限保护早期现金", paragraphs: ["V5 新局的单次租金上限从 ¥3,200 开始，随着银行普通结算回合数每期增加 ¥300，最高 ¥24,000；V4 起始上限 ¥900，每期增加 ¥80，最高 ¥6,500。", "这是限制单次落点支付的风险，而不是降低地契名义租金表；因此在前期，昂贵旅馆不应一次性榨干刚开局的玩家，后期保护会逐渐减弱。"], evidence: "VeilopolyCityLongEconomy.swift: rentCeiling"),
  .init(id: "property-sell", chapter: "property", title: "卖出建筑与库存", subtitle: "需要按组内最高等级撤建", paragraphs: ["出售建筑必须从同颜色组当前最高等级的街区开始，不能越级拆除。普通房屋回到银行库存，售得现金通常等于该地块建设成本的一半。", "旅馆降级成 4 栋房屋时，银行需要有足够的可用房屋库存；银行库存不足时该操作会被拒绝。游戏内的“出售建筑”不是出售地契产权。"], evidence: "Rules.swift: sellOneBuilding"),
  .init(id: "property-mortgage", chapter: "property", title: "地产抵押", subtitle: "产权仍属于你，不再收取租金", paragraphs: ["未抵押且满足建筑条件的产权可以抵押。抵押获得的现金通常为地块标价的二分之一；抵押后的地块不能向到访玩家收租。", "同一颜色组有尚未拆除的房屋或旅馆时，该组地产可能不能抵押。抵押与出售是不同的制度：抵押并不把产权交给银行。"], evidence: "Rules.swift: mortgage, mayMortgage"),
  .init(id: "property-redeem", chapter: "property", title: "赎回抵押地产", subtitle: "本金加上按规则取整的费用", paragraphs: ["赎回一块抵押地产所需的游戏币是：抵押本金 ＋ 向上取整的抵押本金 10% 费用；抵押本金等于地块标价的一半。", "例如 V5 地中海大道价格 ¥720，抵押本金 ¥360，赎回费用 ¥396。赎回前必须持有足够现金，否则系统拒绝，不会自动发放贷款。"], evidence: "Rules.swift: redeem"),
  .init(id: "property-banked", chapter: "property", title: "房屋库存与银行储备不是同一个数", subtitle: "实体库存和游戏币库存分开", paragraphs: ["银行初始 32 栋房、12 座旅馆是实体建造供应约束；¥2,000,000 是 V5 游戏币现金储备。银行即使有大量游戏币，也不代表无限拥有房屋；反过来银行有房屋也不代表能马上兑付到期存款。", "免费建房卡受房屋库存约束；普通玩家的住宅建设还必须支付建设现金。两类库存既独立，又共同影响市面上的地产供给和流动性。"], evidence: "Models.swift: Bank；Rules.swift"),
  .init(id: "cards-deck", chapter: "cards", title: "机会、命运、机遇的真正关系", subtitle: "两种牌堆，不存在第三个网络牌堆", paragraphs: ["代码里仅有两种牌堆 DeckKind：chance（机会）和 chest（命运），各 16 张，总计 32 张。“机遇”是部分机会牌的文字主题，不是额外的抽牌类别。", "落在机会格（7、22、36）从机会堆抽牌；落在命运格（2、17、33）从命运堆抽牌。具体抽到哪张由本局种子、已抽取位置和保存的牌堆顺序决定。"], evidence: "Models.swift；Board.swift；VeilopolyCityLongCards.swift"),
  .init(id: "cards-contents", chapter: "cards", title: "读牌时优先看执行结果", subtitle: "标题、故事与规则效力不同", paragraphs: ["牌面通常包含标题、叙事和明确的执行条款。“市政项目资助”等故事用于增强情境；只有执行条款和 CardEffect 会真正改变现金、位置、监狱状态、房屋库存与其他玩家资金。", "V5 含正负现金、铁路／公共事业移动、退后格数、入狱、建筑维修、出狱卡与免费建房事件；不能仅凭标题判断必定获利。"], evidence: "VeilopolyCityLongCards.swift；Rules.swift: applyCard"),
  .init(id: "cards-reshuffle", chapter: "cards", title: "抽完一轮怎样重洗", subtitle: "不占用掷骰随机流", paragraphs: ["每套牌池的 16 张抽完一轮后，根据同一对局种子、牌堆类型及轮次，调用独立的确定性随机流重新洗牌。", "这不会额外消耗用于骰子或股票行情的随机计数器；相同初始种子和相同行动序列应得到一致的卡牌结果，可用于复盘。"], evidence: "VeilopolyCityLongCards.swift: reshuffleOnCycle"),
  .init(id: "cards-money", chapter: "cards", title: "卡牌金额以文字为准", subtitle: "V5 金额独立写入 CardEffect", paragraphs: ["V5 的普通现金、维修、生日转账和无房建造替代奖励采用 V4 金额的四倍面额，并修改相应牌面文字。例：机会编号 5“城市创新基金”发放 ¥2,600；机会编号 14“供应链合同清算”支付 ¥2,000。", "执行金额不应在落地后再悄悄乘三。银行余额不足发放奖励时，仍可能只先支付部分现金并登记余款。"], evidence: "VeilopolyCityLongCards.swift: blueprintsV5；Rules.swift"),
  .init(id: "cards-freehouse", chapter: "cards", title: "两张最大建设事件", subtitle: "免费房屋优先，现金补偿其次", paragraphs: ["机会编号 13 和命运编号 27 都会尝试在合法自有完整颜色组中赠建一栋房屋，银行实物库存会减一；赠建行动不会收取建筑费。", "两张牌的替代现金分别为 ¥3,200 与 ¥2,400，只在没有合法建造位置或房屋库存不足时使用。并非无条件“房屋＋现金”双重奖励，也不能绕过均衡建造限制。"], evidence: "VeilopolyCityLongCards.swift；Rules.swift"),
  .init(id: "cards-jail", chapter: "cards", title: "出狱卡的重复抽取", subtitle: "同类最多保留一张", paragraphs: ["在 V5 中，机会出狱卡与命运出狱卡各属于自己的牌堆；抽到已有同类卡时，不再无限堆叠，而是尝试从银行领取 ¥1,000 替代奖励。", "若已持有机会卡但没有命运卡，仍可持有另一类。真正的兑付与库存状态以回执为准。"], evidence: "VeilopolyCityLongCards.swift；Rules.swift: jailCard"),
  .init(id: "cards-chain", chapter: "cards", title: "移动卡可能再次触发落点", subtitle: "一次事件不是一定只产生一条结果", paragraphs: ["卡牌可以指定前往第 11、24 或 39 格，前往起点、最近铁路、最近公共事业，或者后退 3 格。新落点仍可能需要购买地产、交租或再抽取事件；引擎为连锁落点设置深度保护。", "被卡牌直接送入监狱时，不应另行套用通常经过起点的工资；最终以当张卡的行动参数和引擎效果为准。"], evidence: "VeilopolyCityLongCards.swift；Rules.swift: resolveLanding"),
  .init(id: "bank-ledger", chapter: "bank", title: "统一银行账本", subtitle: "避免第二个看不见的钱包", paragraphs: ["所有金融交易进入同一 GameState 内的 IntegratedBankLedger；玩家真正能花的钱仍在 Player.cash。储蓄本金、贷款、模拟基金持仓、股票投资组合与待兑付债权是分类记录的权利义务，不是另外一份可用现金。", "操作被拒绝时，原子状态机不会提交半笔变更；只有成功结算才进入本局的可重放行动历史。"], evidence: "IntegratedBanking.swift；Rules.swift；Models.swift"),
  .init(id: "bank-supply", chapter: "bank", title: "V5 游戏币供应量的恒等式", subtitle: "不是银行储备永不变化", paragraphs: ["V5 开局银行持有 ¥2,000,000，玩家四人各持 ¥25,000。任一已经提交的合法动作，应保持“银行储备＋四名玩家现金＝¥2,100,000”。", "买地、建房、税费或买股通常使现金流向银行；工资、银行奖励、贷款与股票卖出会使银行向玩家支付；玩家之间转账只改变玩家间分配，不改变全市货币总量。存款与股票市值不在恒等式中重复计数。"], evidence: "VeilopolyCityLongEconomy.swift；Rules.swift: apply"),
  .init(id: "bank-liquidity", chapter: "bank", title: "银行现金不足时会怎样", subtitle: "不要把账面欠款说成到账", paragraphs: ["银行可用储备不足时，V5 不应凭空印钞来完成到期存款、虚拟基金和股票退出。银行已经承认但未付出的金额可以进入待兑付债权队列，等待后续资金回流。", "待兑付债权有所有者、金额和来源，但不是可以立刻拿去购地的现金。银行资金重新进入后，规则按队列顺序尝试清偿；某些极端数量上限仍需要压力测试。"], evidence: "IntegratedBanking.swift；Rules.swift: claim settlement"),
  .init(id: "bank-deposit", chapter: "bank", title: "存入活期", subtitle: "锁定一个银行期次，约定收益 1.5%", paragraphs: ["V5 活期操作从玩家当前现金中扣除存入本金，登记为独立的储蓄合同。银行金融期数增加至解锁期次后，可申请取回本金及一次性的 1.5% 合同收益。", "例如存入 ¥10,000，满足一个银行期次后名义到期款为 ¥10,150；如果银行只有 ¥1,000 且前面无其他债权，可能先拿到 ¥1,000，余下 ¥9,150 仍登记为银行待兑付债权。"], evidence: "IntegratedBanking.swift: bankDeposit/bankWithdraw；expandedTerms"),
  .init(id: "bank-fixed", chapter: "bank", title: "存入定期", subtitle: "锁定四个银行期次，约定收益 8.5%", paragraphs: ["V5 定期合同使用已配置的 4 期锁定条件和 8.5% 到期收益；未到解锁期的合同不能像活期随意提前取出。", "例如本金 ¥8,000，到期名义金额为 ¥8,680。仅当银行有足够流动资金且符合队列优先级时，才能立即收到全部现金；否则超出部分可能成为待支付债权。"], evidence: "FinanceExpansion.swift；VeilopolyCityLongEconomy.swift；IntegratedBanking.swift"),
  .init(id: "bank-period", chapter: "bank", title: "“期”不是现实分钟", subtitle: "由引擎的普通回合结束推进", paragraphs: ["存款解锁、贷款到期和虚拟投资合同的时间以 completedTurns 记录。正常完成玩家回合时推进银行期数，而不是按照真实设备时钟一分钟算一期。", "掷骰、点击开卡、浏览地契或离开应用不会因为真实时间流逝就自动凭空生息。"], evidence: "Rules.swift: endTurn；IntegratedBanking.swift: advanceTurn"),
  .init(id: "bank-loans", chapter: "bank", title: "贷款本金、次数、抵押条件", subtitle: "贷款不是另一份免费补助", paragraphs: ["V5 有四档合同利率，按当局玩家既往借款次数顺序分别为 6.5%、8.5%、11%、14.5%；金额上限按持有的合法未抵押产权数量分档：0 块 ¥6,000；1 块 ¥12,000；2 块 ¥24,000；3 块及以上 ¥40,000。", "在规则允许的 1～12 个银行期次内，贷款利息按照整份合同的本金一次计算，不按每期重复收取。例：首次贷款 ¥5,000，名义应还总额 ¥5,325；六期和三期改变到期时间，不自动使上述一次利息叠加六次。"], evidence: "VeilopolyCityLongEconomy.swift: expandedTerms；IntegratedBanking.swift: bankBorrow"),
  .init(id: "bank-credit", chapter: "bank", title: "贷款何时被拒绝", subtitle: "银行必须为已有兑付义务保留空间", paragraphs: ["V5 对新增贷款实行额度、抵押、次数和银行流动性双层限制。风险计算将未偿存款、投资、待兑付债权、股票潜在卖出金额和银行现存资金纳入评估；当已有债权未付、贷款逾期或已知应付款高于银行现金时，可以拒绝新贷款。", "目前以总货币基数的 12% 或已测算的责任加缓冲形成受保护储备，并以总货币基数的 25% 设定总未偿贷款上限，均为实验性游戏参数，不是现实金融监管标准。"], evidence: "VeilopolyFinancialStability.swift；IntegratedBanking.swift"),
  .init(id: "bank-repay", chapter: "bank", title: "主动还款与到期自动处理", subtitle: "应偿总额不一定等于原本金", paragraphs: ["贷款合同记录本金、利率、到期期数和总应还额。主动归还需要足够现金；到期时符合版本规则可能自动还款，逾期会限制新增存款、贷款、虚拟投资和股票买入。", "若同时发生一笔应收收益与一笔贷款到期，不要仅根据账面资产数额判断会被自动抵销。必须查看本局现金、金融期数和实际引擎结算回执。"], evidence: "IntegratedBanking.swift；VeilopolyBankAutomation.swift"),
  .init(id: "bank-investments", chapter: "bank", title: "三种虚拟投资", subtitle: "稳健基金、创业项目、模拟指数", paragraphs: ["V5 支持稳健基金、创业项目、模拟指数三种游戏内模拟合同，合同锁定期分别为 5、4、3 个银行期次；每种产品均有 6 档预定义到期系数，可能盈利也可能亏损。", "单笔投资从玩家现金中扣除本金，到期按照合同 ID 所属的独立确定性抽取确定结果，不因重复点击结算就重新掷一次随机数。没有对应持仓或未到期会被拒绝。"], evidence: "FinanceExpansion.swift: draftDurations；IntegratedBanking.swift: bankSettle"),
  .init(id: "bank-investtable", chapter: "bank", title: "投资结果的全部六档系数", subtitle: "基点 10,000 表示返还本金的 100%", paragraphs: ["稳健基金六档是 [8,000、9,500、10,500、11,500、12,500、13,500] 基点；创业项目为 [4,500、7,000、9,000、12,000、16,000、21,000]；模拟指数为 [6,500、8,500、10,000、12,000、14,500、18,000]。", "例如创业项目投入 ¥10,000，抽中 4,500 基点仅返还 ¥4,500；抽中 21,000 基点名义返还 ¥21,000。上述是可能结果集合，不是收益保证或真实金融概率建议；银行实际现金不足时支付可延后。"], evidence: "VeilopolyCityLongEconomy.swift: terms；FinanceExpansion.swift"),
  .init(id: "bank-credit-risk", chapter: "bank", title: "风险四档怎样看", subtitle: "stable、guarded、stressed、crisis", paragraphs: ["风险页面显示 stable（稳定）、guarded（警戒）、stressed（压力）、crisis（危机）。它们由当前储备、待兑付债权、银行未来合同义务、股票退出价值及逾期贷款等状态导出，是诊断结果，不是实际金融机构评级。", "进入危机不等于所有玩家立即破产；可能出现不能申请新贷款、卖股后待兑付、领取工资出现银行欠款，或者股票价格受到负向宏观压力。风险级别随新的合法交易而变化。"], evidence: "VeilopolyFinancialStability.swift；VeilopolyCityLongEconomy.swift"),
  .init(id: "stock-five", chapter: "stock", title: "五只股票的身份", subtitle: "本地构造的虚构公司", paragraphs: ["VTL＝维尔交通（交通）；AUR＝极光能源（能源）；MNT＝薄荷港湾（消费）；NOV＝新星工坊（工业）；ORB＝轨道系统（科技）。这些名称是游戏内虚构证券，不是任何现实交易所的正式代码。", "每只股票记录基础价、当前价、前收盘价、涨跌与走势图。行情由独立种子、市场状态、个股扰动及 V5 宏观压力共同决定，不需要联网拉取实时证券数据。"], evidence: "StockMarket.swift: initial/advance"),
  .init(id: "stock-base", chapter: "stock", title: "V5 五只股票的初始价格", subtitle: "价格以“分”为最小模型单位", paragraphs: ["V5 在经典基础报价的整数分上乘 24 倍：VTL ¥444.00、AUR ¥633.60、MNT ¥283.20、NOV ¥940.80、ORB ¥1,248.00。这只是新局初始标定，不是固定成交价；后续价格由 Tick 更新。", "如果界面显示股价、股数和预估总价，必须区分“每股价格”与“整笔订单金额”，也不能把以分存储的整数 44,400 误读成 ¥44,400。"], evidence: "StockMarket.swift: quoteScale；VeilopolyCityLongEconomy.make"),
  .init(id: "stock-buy", chapter: "stock", title: "买股票的完整步骤", subtitle: "选择标的 → 输入股数 → 预估 → 买入", paragraphs: ["打开模拟证券交易终端，选择 VTL、AUR、MNT、NOV 或 ORB，输入正整数股数，并核对系统显示的每股报价、订单本金、手续费以及实际现金扣减。", "每笔买入需要持有足够的 Player.cash。当前每次指令合法股数为 1～10,000 股，每人同一标的总持仓不得超过 100,000 股；停牌期间不能成交。确认买入后股票记录进入本人持仓，不会变成另一份现金。"], evidence: "StockMarket.swift: estimateBuy/buy；UI.swift"),
  .init(id: "stock-sell", chapter: "stock", title: "卖股票的完整步骤", subtitle: "选择已经持有的标的与股数", paragraphs: ["卖出需要确认持有数量充足，且标的没有停牌。系统先按当前模拟报价估算卖出额与手续费，再减少所持股数。", "V5 如果银行储备不足，股票持仓依引擎成交后只能立即取得银行可付出的部分，剩余款项成为“stockExit”待兑付债权；因此“卖出成功”不等于“全部现金已到账”。"], evidence: "StockMarket.swift: estimateSell/sell；IntegratedBanking.swift"),
  .init(id: "stock-fee", chapter: "stock", title: "手续费、取整和最低额", subtitle: "不能只算股价乘股数", paragraphs: ["股票 V5 使用增强市场算法版本 3，单笔订单手续费率为 0.25%，最低 ¥1 游戏币。买入订单的整笔价格按分转游戏币时可能向上取整，卖出时按整数游戏币结算，然后再扣手续费。", "示例：以 ¥444.00 买入 10 股 VTL，买入本金 ¥4,440，名义手续费 max(¥1, 4440×0.25% 按整数计算)＝¥11，合计扣除 ¥4,451。实际报价改变时应重新计算。"], evidence: "StockMarket.swift: estimateBuy/estimateSell"),
  .init(id: "stock-profit", chapter: "stock", title: "持仓成本与浮动盈亏", subtitle: "账面盈利并不等于银行会立即付款", paragraphs: ["持仓成本会包含实际成交价和费用；持有期间价格上升或下降产生的浮动盈亏是估值，不会自动改变玩家现金。卖出发生后才产生真正的已实现交易现金与手续费。", "与地产一样，股票仅属于游戏内账面资产；如果出现银行危机，出售资产也可能形成待兑付债权，投资组合的市值不能直接当作银行现款。"], evidence: "StockMarket.swift: portfolio/realizedPnLCents；IntegratedBanking.swift"),
  .init(id: "stock-tick", chapter: "stock", title: "什么会让价格更新", subtitle: "固定 Tick，不是现实股市分钟 K 线", paragraphs: ["引擎维护行情 Tick、随机计数、市场状态、模拟成交量、近期价格历史及停牌计数。V5 加入由全局玩家现金、楼宇建设、未偿贷款和资金集中程度形成的宏观信号。", "该宏观信号会限制在一个有限区间内作用于 Tick；银行警戒、压力与危机状态可能带来负向压力。但并没有真实公司订单簿、交易所撮合或现实宏观新闻。"], evidence: "StockMarket.swift: advanceChecked；VeilopolyCityLongEconomy.marketPressure"),
  .init(id: "stock-halt", chapter: "stock", title: "停牌是什么意思", subtitle: "短期不接受买卖指令", paragraphs: ["达到模拟交易规则的价格上下界后，某只股票可能进入有限 Tick 的停牌状态。停牌期间即使你有足够现金或者足够股票，交易指令仍会被拒绝，已拥有持仓不会因此消失。", "不要把停牌理解成银行自动赔付或股票直接归零；停牌期间仍可查看持仓账本。"], evidence: "StockMarket.swift: stockTradingHalted；advanceChecked"),
  .init(id: "stock-out-of-market", chapter: "stock", title: "这不是一座真实证券交易所", subtitle: "不存在真实公司财务模型", paragraphs: ["虽然股价会响应部分城市现金变化，但当前实现没有完整企业资产负债表、限价单订单簿、交易对手撮合、真实市场深度或可兑换现金的机制。", "本书不应使用“收益有保证”“真实经济必然如此”“股票一定可以卖掉换现”等措辞。真实的交易回执只证明本游戏内一次动作已经提交。"], evidence: "StockMarket.swift；MACRO_FINAL_20261108.md"),
  .init(id: "market-direct", chapter: "market", title: "直接给指定玩家转账", subtitle: "不是交易提案，不需要对方接受", paragraphs: ["在当前管理阶段打开“城市合同与玩家转账”，从下拉菜单选择非本人且未破产的目标玩家，输入 1～1,000,000 的正整数游戏币金额，点击“立即转账”。", "转账完成后付款者现金减少、收款者现金等量增加；银行储备不会因为这笔双方转移而改变。余额不足、目标无效、选择本人或目标已破产时应拒绝。该功能只在具有有限银行规则的单机新局提供。"], evidence: "UI.swift: tradeProposalPanel；Rules.swift: transferCash"),
  .init(id: "market-contract", chapter: "market", title: "双边交易合同", subtitle: "对方接受前没有交割", paragraphs: ["交易合同可以约定双方各支付多少现金、交出哪些允许交易的地产，以及当前版本允许的出狱卡。提案方先提出条件，收件方可以接受、拒绝或依规则还价；不是一键强制转走对方资产。", "一旦双方合法接受，资产与现金在同一引擎动作中交换。正在显示的“产权交换协议”是提案，不是已成交凭证；如果发起到接受期间资产条件变化，引擎应再次核查条件。"], evidence: "Rules.swift: proposeTrade/acceptTrade；VeilopolyCivicText.swift"),
  .init(id: "market-property-constraint", chapter: "market", title: "为什么有些产权不能加入交易", subtitle: "建筑组的完整性限制", paragraphs: ["在交易协议中提出产权交换时，引擎检查产权人是否正确、是否有重复地块，及同色组是否仍存在建筑。存在尚未拆除建筑的组不能通过普通交易绕过建筑与产权规则。", "抵押、房屋、现金和出狱卡各有不同的法律属性；“拥有某张地契”并不自动赋予越过所有条件的自由转让权。"], evidence: "Rules.swift: validTransfer"),
  .init(id: "market-flow", chapter: "market", title: "一个动作怎样影响全市经济", subtitle: "同一引擎结算，不是多个独立钱包", paragraphs: ["购买地产时，买家现金下降、银行储备上升、产权从无主变成有主；买股票时，玩家现金下降、证券持仓上升，买入金额进入银行储备。", "申请贷款会把银行储备转成玩家当前现金，同时形成未来应还的贷款合同；支付租金通常只在玩家间划转，总货币量不变，但财富集中度可能变化并影响股票行情压力。"], evidence: "Rules.swift；IntegratedBanking.swift；VeilopolyCityLongEconomy.swift"),
  .init(id: "market-equilibrium", chapter: "market", title: "扩大货币量不等于更公平", subtitle: "价格、工资、租金与贷款一起校准", paragraphs: ["V5 将初始玩家现金从 V4 的 ¥7,200 提高至 ¥25,000，银行储备从 ¥160,000 提高至 ¥2,000,000，同时将地产标价和建设成本从经典的 3 倍提高为 12 倍、街区名义租金从 2 倍提高为 8 倍。", "这只是设计上的同比扩容，是否改善 20 分钟迅速结束、破产过早等问题需要玩家实测与多种子统计，不能仅凭币值提高就宣布平衡已经实现。"], evidence: "VeilopolyCityLongEconomy.swift；MacroFinalSeedStressTests.swift"),
  .init(id: "market-wealth", chapter: "market", title: "什么叫财富集中", subtitle: "现金不是唯一控制力", paragraphs: ["现金在四位玩家之间的分布、集中控制的地组、建房数量、银行当前可放贷金额和模拟股票组合共同构成游戏内商业环境。", "宏观股价信号中的“集中度”只从玩家当前现金差距推导，并不等于现实经济学的完整基尼系数，也没有真实的企业税务、库存产能与货币政策委员会。"], evidence: "VeilopolyCityLongEconomy.marketPressure"),
  .init(id: "crisis-risk", chapter: "crisis", title: "金融危机不是“全员立即破产”", subtitle: "风险传导与个人破产是两件事", paragraphs: ["当银行兑现义务压力增大，风险评估可以进入 guarded、stressed 或 crisis 状态；这可能收紧新增贷款、改变股票行情的宏观压力、让工资或投资收益部分转为待兑付债权。", "只有特定玩家本人出现无法清偿的正式债务并触发清算规则，才可能破产。银行资金不足不会自动将另外三名玩家同时宣告破产。"], evidence: "VeilopolyFinancialStability.swift；Rules.swift"),
  .init(id: "crisis-reserves", chapter: "crisis", title: "银行冗余如何计算", subtitle: "200 万银行余额不是无限保险", paragraphs: ["V5 开局银行 ¥2,000,000 对玩家现金 ¥100,000，比例为 20:1；但这只是开局现金结构，并非银行资产负债表的真实资本充足率。", "风险检查同时估计待兑付债权、存款与约定收益、投资可能最大兑付、当前股票市值及到期贷款。只有实际储备能够覆盖风险预算、已有债权与最低保护要求时，才允许新增可选贷款。"], evidence: "VeilopolyFinancialStability.swift"),
  .init(id: "crisis-pool", chapter: "crisis", title: "受保护储备和全市场授信", subtitle: "限制新增风险，不冻结全部玩法", paragraphs: ["V5 的授信保护机制将货币总额的 12% 作为基础储备参照，并将已测算的兑付责任与额外缓冲纳入计算；未偿贷款本金总额最多按货币总额的 25% 预算。", "以 V5 总量 ¥2,100,000 计算，12% 是 ¥252,000，25% 是 ¥525,000。这两个值是当前游戏实验参数而非现实法律要求，且最终可放贷额度还需扣除已有贷款、未兑付债权及其他条件。"], evidence: "VeilopolyFinancialStability.swift"),
  .init(id: "crisis-queue", chapter: "crisis", title: "什么是 FIFO 待兑付队列", subtitle: "先来先结，不允许超额铸币", paragraphs: ["V5 的某些银行必须支付款、到期存款、投资清算与卖股付款在现金不足时，会记录债权所有者、金额、来源并进入有序队列。之后银行收到合法资金回流时，先按队列顺序逐项兑付。", "债权存在不代表玩家手上有可支配现金。队列设置了总记录上限，极端情况下多份破产遗产的高额债权可能触发拒绝保护；这条极端边界尚未通过完整压力验收。"], evidence: "IntegratedBanking.swift；Rules.swift: bankClaimSettlement"),
  .init(id: "crisis-salary", chapter: "crisis", title: "危机时的工资和卡牌补助", subtitle: "理论应得与实际到账可不同", paragraphs: ["V5 经过起点的理论工资为 ¥3,200；若银行当前没有足够的现金，应根据已有规则确定立即支付部分、尚未兑付金额和原有队列优先级。", "界面展示的“起点工资”是名义数，真正增加的现金必须以成功提交的回执及玩家现金变化为准；未到账的部分在银行债权记录中追踪，而不是凭空出现。"], evidence: "Rules.swift: payBank/applyMovement"),
  .init(id: "crisis-debt", chapter: "crisis", title: "债务不足与“债务阶段”", subtitle: "进入清算通知不等于已经破产", paragraphs: ["玩家欠租或欠税时，规则可能先尝试通过卖房、抵押与可立即兑现的金融资产凑足现金；不足时进入明确的 debt 债务阶段。", "如果银行自己缺钱，未到手的存款价值或股票市值不能假装已兑换成现金用于偿债。V5 已加入保护：强制清算不能调用不可即时兑付的银行现金，否则保持资产原状并进入债务处理。"], evidence: "IntegratedBanking.swift: releaseAvailableSavingsForDebt；Rules.swift"),
  .init(id: "crisis-bankruptcy", chapter: "crisis", title: "破产后现金和地产怎样处置", subtitle: "由合法债权人决定基础继承方向", paragraphs: ["当前引擎在正式破产阶段处理剩余可用现金、产权以及银行金融资产。若债权人为其他玩家，规则倾向于将相关可继承资产和未兑付权利交给该玩家；若债权人是银行，则相应银行债务与破产资产需要清算。", "V5 已添加非现金金融遗产处理，但完整遗产继承的极端场景、多人债权顺序与队列上限仍是未通过验收的工程风险；不要向玩家承诺全部复杂危机都能无故障结清。"], evidence: "Rules.swift: bankrupt；IntegratedBanking.closeBankruptAccount"),
  .init(id: "crisis-estate", chapter: "crisis", title: "破产金融遗产不等于现金发放", subtitle: "存款与股票应当保留债权属性", paragraphs: ["V5 玩家对玩家债权场景下，破产人剩余的存款合同、虚拟投资、股票和原有待兑付银行债权会依据当前研发逻辑移交给合法债权人；接收方持股达到单标的上限时，超额部分可能折为待兑付银行债权。", "这是为避免破产时突然创造货币的研发规则，不代表证券市场有真实清算所或银行保证所有资产能立刻按标价换成现金。"], evidence: "IntegratedBanking.swift: closeBankruptAccount；SystemicRiskV5EstateTests.swift"),
  .init(id: "crisis-safety", chapter: "crisis", title: "危机状态中的操作原则", subtitle: "核对现金、合同、债权三种数字", paragraphs: ["在银行风险面板里分别查看当前储备、已登记待兑付、预计未来兑现负债和可新增贷款空间。若现金不足，不能依赖尚未兑付的“卖股收益”安排下一笔地价或租金支付。", "反复点击被拒绝的交易不应改变市场随机种子、现金或持仓；如果重复点击产生多次实际扣款，则属于需要提交黑匣子或存档证据的程序缺陷。"], evidence: "VeilopolyFinancialStability.swift；Rules.swift"),
  .init(id: "save-two-slots", chapter: "save", title: "双槽本地存档", subtitle: "受校验的 JSON 与最近可用版本", paragraphs: ["单机存档使用两个交替的 JSON 槽位，记录 GameState、规则版本、行动编号、哈希以及可能存在的股票执行回执。写入采取原子方式并附独立校验，以降低一次写入中断导致两份存档同时损坏的风险。", "双槽和 atomic 写入并不是硬件级永不丢数据保证；断电或异常退出时尚未落盘的极近期股票时间步仍可能丢失。不要为修错随意删除应用数据。"], evidence: "GameSaveStore.swift"),
  .init(id: "save-versions", chapter: "save", title: "旧存档与新规则如何共存", subtitle: "禁止静默重新定价", paragraphs: ["经典对局、V3、V4、V5 各自具有对应规则与资金结构。读取旧 V4 存档后，不应该把银行现金强制扩成 ¥2,000,000，也不应该把原来的地契价格乘成 V5；以载入状态携带的 financeRuleVersion 为准。", "游戏内修改卡牌文案、规则手册及其他只读 UI 不应修改保存校验或网络状态哈希。需要升级规则时，应明确新建一局或经过审核的迁移，而不是暗中改变旧回合。"], evidence: "VeilopolyCityLongEconomy.make/makeV4；IntegratedBanking.decode；GameSaveStore.swift"),
  .init(id: "save-restore", chapter: "save", title: "如何继续之前的一局", subtitle: "先确认存档确实存在", paragraphs: ["返回游戏大厅后，若有有效的单机存档，界面将根据实际可恢复记录提供继续对局相关入口；继续前确认当前玩家、现金、产权及回合信息。", "如果看不到对局，不代表后台一定删库；需要检查应用版本、沙盒数据、存档双槽校验与恢复错误日志。无法在当前聊天中访问的手机存档不应由说明书虚构其存在。"], evidence: "GameSaveStore.swift；UI.swift"),
  .init(id: "save-ai", chapter: "save", title: "AI 的具体职责", subtitle: "独立合法行动，不拥有作弊预算", paragraphs: ["AI 玩家与人类使用同一规则引擎和同样的 GameState 现金、地产和债务状态；AI 等级含保守、均衡和激进，影响现金储备与产权购买偏好。", "新 V5 的 AI 策略与早期破产率是否合理仍有待多种子实际运行。没有证据支持“AI 已达到最强”“100 局全部完成”等说法。"], evidence: "VeilopolyAI/AI.swift；MacroFinalSeedStressTests.swift"),
  .init(id: "save-network", chapter: "save", title: "本地双机联机到底到哪一步", subtitle: "不把接口存在说成已经适配 V5", paragraphs: ["项目包含主客端房间状态、邀请、接受、提案、提交、重同步及快照校验相关源码；VeilLink 主应用已有过通信层接线的研发工作。", "但当前 V5 游戏货币制度尚未完成对两手机的版本化协商，不能假定一台手机按 V5 游戏币，另一台仍按经典现金仍然能合法联机。完整 iOS 编译、两设备蓝牙和 Wi-Fi 实测未在本轮验收。"], evidence: "VeilopolyNet/LiveRoom.swift；CHECKPOINT.md"),
  .init(id: "save-ios", chapter: "save", title: "iOS 15 支持声明的真实含义", subtitle: "部署目标不等于实测通过", paragraphs: ["Swift Package 的平台目标包含 iOS 15，游戏使用 SwiftUI 与 SpriteKit 相关组件，但这仅证明项目声明了最低部署条件。", "由于最新分支没有在本轮通过 Apple SDK 构建、iPhone 7 实机触控、性能和恢复验收，说明书不能写“iOS 15 机型已经稳定兼容”。"], evidence: "Package.swift；VeilopolyGuideSheet.swift；CHECKPOINT.md"),
  .init(id: "help-disabled", chapter: "help", title: "按钮为什么是灰色", subtitle: "优先看阶段、余额和法律条件", paragraphs: ["常见原因有：不是本人回合、当前处于拍卖或交易确认、资金不足、股票停牌、缺少整组街道、银行房屋不足、存款尚未解锁或已有逾期贷款。", "先查看按钮附近的拒绝说明和当前 GameState；不要在界面反馈之前连续点击。确认条件满足仍失败时，应记录操作步骤、版本号与原始错误码。"], evidence: "GamePresentation.swift；UI.swift；Rules.swift"),
  .init(id: "help-banklow", chapter: "help", title: "银行显示危机但我仍有钱", subtitle: "个人现金与系统流动性不同", paragraphs: ["玩家的 Player.cash 是已经到账的游戏币；银行危机说明对未来全部兑付责任的覆盖率恶化，或者已有债权和逾期贷款。个人仍可持有现金、买地或向其他玩家转账，但某些由银行新支付的款项不能再被保证。", "银行一旦获得玩家购地、缴税或合法存款等资金回流，旧债权可能按顺序偿还。"], evidence: "VeilopolyFinancialStability.swift；Rules.swift"),
  .init(id: "help-stockpay", chapter: "help", title: "股票卖出后钱没有全部到账", subtitle: "检查 stockExit 待兑付债权", paragraphs: ["若持仓减少而可用现金只增加一部分，检查银行面板的“我的待兑付银行债权”，查看是否存在来源为 stockExit 的银行付款承诺。", "这与交易被拒绝是两种状态：前者已经改变持仓并保留现金债权，后者在原子引擎中不应改变任何持仓。"], evidence: "IntegratedBanking.swift: disburseMatured；UI.swift"),
  .init(id: "help-card-value", chapter: "help", title: "卡面金额与实收金额不一致", subtitle: "先区分“名义奖励”与“延付”，再核对规则版", paragraphs: ["在 V5，卡牌现金效果按 V4 标定的 4 倍生成，规则文本同步修改；示例：城市创新基金是 ¥2,600。", "如果实收现金较少，应先检查当时银行储备、老债权优先级与已新增的个人待兑付金额。如果文本、账本与行动回执互相矛盾，属于需要提交问题单的程序缺陷。"], evidence: "VeilopolyCityLongCards.swift；Rules.swift"),
  .init(id: "help-notfinished", chapter: "help", title: "为什么到几千步还没有获胜", subtitle: "测试步数上限不等于结束", paragraphs: ["有限现金和保护机制可能让玩家更长时间保有资产；100 种子压力测试设置每局最多 1,200 次引擎动作，以观察自然完局与封顶未完局比例，不意味着每局应在 1,200 次动作内自动判胜。", "测试完成前不能把“平均 20 分钟”“已改善到一小时”等推测写成正式质量保证。"], evidence: "MacroFinalSeedStressTests.swift；CHECKPOINT.md"),
  .init(id: "help-debug", chapter: "help", title: "遇到崩溃或资金异常如何反馈", subtitle: "保留实际证据，不修改本地数据库", paragraphs: ["尽量记录机型、iOS 版本、对局规则版本、玩家席位、步骤序号、操作前后现金、银行储备、待兑付债权、截图或短视频，以及是否刚刚从旧存档恢复。", "如果系统提供黑匣子导出，请通过已存在的诊断入口提供原始日志；不要发送账号密码、密钥、隐私聊天内容，也不要通过删除存档试探能否“修复”数据库。"], evidence: "VeilopolySaveStore.swift；CHECKPOINT.md"),
  .init(id: "help-legal", chapter: "help", title: "现实金钱与投机的边界", subtitle: "全部为不可兑换的桌游游戏币", paragraphs: ["游戏内股票与基金、银行利率、抵押和贷款均为虚拟制度，不能兑换真钱、不能直接对接现实银行或券商，也不是彩票、赌博或真实投资工具。", "不要将游戏内收益曲线用于现实市场的投资判断；本书的利率、报价和贷款示例只是说明引擎怎样做整数计算。"], evidence: "FinanceExpansion.swift；StockMarket.swift"),
  .init(id: "board-00", chapter: "appendix", title: "第 00 格｜起点", subtitle: "不可作为普通地产购买", paragraphs: ["跨过或根据卡牌移动至此时，依本局工资与银行流动性规则结算。", "本格既没有普通地契售价，也不能作为玩家住宅建设的位置；不要套用外部实体桌游的私人家规。"], evidence: "Board.swift；Rules.swift"),
